import React from 'react';

// We define a function that takes a string as an argument and returns its reverse
const reverseString = (str: string): string => {
  // We split the string into an array of characters
  const charArray = str.split('');
  // Then we reverse the array
  const reversedArray = charArray.reverse();
  // And finally, we join the array back into a string and return it
  return reversedArray.join('');
};

// Example usage:
const originalString = 'Hello, world!';
const reversedString = reverseString(originalString);
console.log(reversedString); // This will log: '!dlrow ,olleH'

// We can also use this function in a React component:
const App: React.FC = () => {
  const [input, setInput] = React.useState('');
  const [reversed, setReversed] = React.useState('');

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setInput(event.target.value);
    setReversed(reverseString(event.target.value));
  };

  return (
    <div>
      <input type="text" value={input} onChange={handleInputChange} />
      <p>Reversed: {reversed}</p>
    </div>
  );
};

export default App;
